package com.univmar.project.domain; import com.univmar.customer.domain.Customer; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
@Entity @Table(name="customer_project") public class Project { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id",nullable=false) private Customer customer; @Column(nullable=false,length=180) private String name; @Column(length=180) private String location; @Column(length=80) private String projectType; @Column(columnDefinition="text") private String description; @Column(name="estimated_value",precision=14,scale=2) private BigDecimal estimatedValue; private LocalDate startDate; private LocalDate requiredDeliveryDate; @Column(length=180) private String assignedSalesAgent; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private ProjectStatus status=ProjectStatus.LEAD; @Column(columnDefinition="text") private String notes; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; protected Project(){} public Project(Customer c,String name,String location,String type,String description,BigDecimal value,LocalDate start,LocalDate delivery,String agent,ProjectStatus status,String notes){id=UUID.randomUUID();update(c,name,location,type,description,value,start,delivery,agent,status,notes);} public void update(Customer c,String name,String location,String type,String description,BigDecimal value,LocalDate start,LocalDate delivery,String agent,ProjectStatus status,String notes){customer=c;this.name=name;this.location=location;projectType=type;this.description=description;estimatedValue=value;startDate=start;requiredDeliveryDate=delivery;assignedSalesAgent=agent;this.status=status;this.notes=notes;} @PrePersist void dates(){createdAt=updatedAt=Instant.now();}@PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public Customer getCustomer(){return customer;} public String getName(){return name;} public String getLocation(){return location;} public String getProjectType(){return projectType;} public String getDescription(){return description;} public BigDecimal getEstimatedValue(){return estimatedValue;} public LocalDate getStartDate(){return startDate;} public LocalDate getRequiredDeliveryDate(){return requiredDeliveryDate;} public String getAssignedSalesAgent(){return assignedSalesAgent;} public ProjectStatus getStatus(){return status;} public String getNotes(){return notes;} }
